// 일반 폴링 — N초마다 물어봄 (지연=주기, 빈 요청 많음)
setInterval(async () => {
  const res = await fetch('/updates?since=' + lastSeq);
  const changes = await res.json();
  if (changes.length) apply(changes);   // 없으면 빈손(낭비)
}, 5000);

// 롱 폴링 — 서버가 새 게 생길 때까지 응답을 붙잡음
async function longPoll() {
  const res = await fetch('/updates?since=' + lastSeq); // 서버가 hang
  apply(await res.json());   // 새 게 생기면 즉시 응답
  longPoll();                // 받자마자 다시 (빈 응답↓, 지연≈실시간)
}

// 서버 (Node) — 연결을 닫지 않고 이벤트를 계속 씀
res.writeHead(200, {
  'Content-Type': 'text/event-stream',
  'Cache-Control': 'no-cache',
  'Connection': 'keep-alive',
});
res.write('id: 1\n');
res.write('data: ' + JSON.stringify({ progress: 20 }) + '\n\n');

// 클라 — 브라우저 내장 EventSource (자동 재연결 + Last-Event-ID)
const es = new EventSource('/progress');
es.onmessage = (e) => update(JSON.parse(e.data));
// 끊기면 EventSource 가 알아서 재연결하고, 마지막 id 이후만 받음
